// Reads the topic form from Telegram. If nobody answered before the time limit, has_topic is false.
// Telegram returns form answers by field label, so keep these labels in step with the "Ask for Topic" form.
const LABELS = {
  topic: 'Newsletter topic',
  feature: 'Anything to feature',
  offer: 'Offer to include',
  notes: 'Notes for the writer',
};
const s = $('Settings').first().json;
const answers = $json.data ?? {};
const read = (key, max) => {
  const value = answers[LABELS[key]] ?? answers[key];
  return value === undefined || value === null ? '' : String(value).replace(/\s+\n/g, '\n').trim().slice(0, max);
};

const now = $now.setZone(s.timezone);
const topic = read('topic', 300);

return [{
  json: {
    has_topic: Boolean(topic),
    topic,
    feature: read('feature', 2000),
    offer: read('offer', 255),
    notes: read('notes', 1500),
    today: now.toFormat('cccc, LLLL d, yyyy'),
    date: now.toFormat('yyyy-MM-dd'),
  },
}];

