// Numbers the research findings and writes the planner's brief: the owner's request plus the research.
const s = $('Settings').first().json;
const t = $('Read Topic').first().json;
const r = $json.output ?? {};
const clean = (v, max = 600) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const list = (v) => (Array.isArray(v) ? v : []).map((x) => clean(x, 300)).filter(Boolean);

const findings = (Array.isArray(r.findings) ? r.findings : [])
  .filter((f) => f && clean(f.fact))
  .slice(0, 12)
  .map((f) => ({
    fact: clean(f.fact),
    why_it_matters: clean(f.why_it_matters, 300),
    source_title: clean(f.source_title, 150),
    source_url: /^https?:\/\//.test(String(f.source_url ?? '')) ? String(f.source_url).trim() : '',
  }));
const sectionCount = Math.min(6, Math.max(2, Number(s.section_count) || 4));

const prompt = [
  'NEWSLETTER REQUEST',
  `Topic: ${t.topic}`,
  `The owner wants to feature: ${t.feature || 'nothing specific'}`,
  `Offer: ${t.offer ? `${t.offer} (the email shows it in its own box)` : 'none. Do not mention any discount or deal.'}`,
  `Notes from the owner: ${t.notes || 'none'}`,
  `Today: ${t.today}`,
  `Sections to plan: ${sectionCount}`,
  '',
  'RESEARCH SUMMARY',
  clean(r.summary, 1000) || 'No summary.',
  '',
  'RESEARCH FINDINGS (number | fact | why it matters | source)',
  findings.length
    ? findings.map((f, i) => `${i + 1} | ${f.fact} | ${f.why_it_matters} | ${f.source_title} ${f.source_url}`.trim()).join('\n')
    : 'No findings. Plan the issue around the restaurant and the owner\'s request.',
  '',
  'ANGLES THE RESEARCHER SUGGESTS',
  list(r.angles).map((a) => `- ${a}`).join('\n') || 'none',
  '',
  'SEASONAL OR LOCAL HOOKS',
  list(r.hooks).map((h) => `- ${h}`).join('\n') || 'none',
].join('\n');

return [{ json: { prompt, findings, section_count: sectionCount, research_summary: clean(r.summary, 1000) } }];

