// Turns the plan into one item per section for the Section Writer Agent, with the research findings it should use.
const t = $('Read Topic').first().json;
const brief = $('Build Planning Brief').first().json;
const plan = $json.output ?? {};
const findings = brief.findings ?? [];
const clean = (v, max = 400) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const list = (v, max = 6) => (Array.isArray(v) ? v : []).map((x) => clean(x, 200)).filter(Boolean).slice(0, max);

const sections = (Array.isArray(plan.sections) ? plan.sections : []).filter((x) => x && clean(x.title)).slice(0, 6);
if (!sections.length) throw new Error('The planner returned no sections. Run the workflow again.');
const outline = sections.map((x, i) => `${i + 1}. ${clean(x.title, 80)}`).join('\n');

return sections.map((section, i) => {
  const numbers = [...new Set((Array.isArray(section.finding_numbers) ? section.finding_numbers : []).map(Number))]
    .filter((n) => Number.isInteger(n) && n >= 1 && n <= findings.length);
  const assigned = numbers.map((n) => findings[n - 1]);
  const prompt = [
    `Write section ${i + 1} of ${sections.length} of the newsletter.`,
    '',
    `Newsletter topic: ${t.topic}`,
    `Newsletter headline: ${clean(plan.headline, 120)}`,
    `The owner wants to feature: ${t.feature || 'nothing specific'}`,
    `Offer in this issue: ${t.offer || 'none. Do not mention any discount or deal.'}`,
    `Notes from the owner: ${t.notes || 'none'}`,
    '',
    'THIS SECTION',
    `Title: ${clean(section.title, 80)}`,
    `What it should say: ${clean(section.angle, 400)}`,
    `Key points:\n${list(section.key_points).map((p) => `- ${p}`).join('\n') || '- your choice'}`,
    `Menu items or features it can mention: ${list(section.mention_items).join('; ') || 'none'}`,
    '',
    'RESEARCH FOR THIS SECTION',
    assigned.length
      ? assigned.map((f) => `- ${f.fact} (source: ${f.source_title} ${f.source_url})`.trim()).join('\n')
      : 'None assigned. Search with Tavily_Search only if the section needs a fact.',
    '',
    'ALL SECTIONS IN THIS ISSUE (do not repeat what the others cover)',
    outline,
  ].join('\n');
  return {
    json: {
      section_number: i + 1,
      title: clean(section.title, 80),
      prompt,
      assigned_sources: assigned.filter((f) => f.source_url).map((f) => ({ title: f.source_title || f.source_url, url: f.source_url })),
    },
    pairedItem: { item: 0 },
  };
});

