// Puts the plan and the written sections together into one newsletter draft.
// A section whose writer failed is left out; the run stops only if every section failed.
const plan = $('Newsletter Planner').first().json.output ?? {};
const planned = $('Split Sections').all();
const written = $input.all();
const clean = (v, max = 2000) => String(v ?? '').replace(/[ \t]+/g, ' ').trim().slice(0, max);

const sections = [];
const sources = new Map();
const errors = [];
written.forEach((item, i) => {
  const out = item.json.output;
  const paragraphs = (Array.isArray(out?.paragraphs) ? out.paragraphs : []).map((p) => clean(p, 1200)).filter(Boolean).slice(0, 3);
  if (!paragraphs.length) {
    errors.push(`Section ${i + 1}: ${clean(item.json.error?.message ?? item.json.error ?? 'no text returned', 200)}`);
    return;
  }
  sections.push({ title: clean(out.title, 80) || planned[i]?.json.title || '', paragraphs });
  const used = [...(Array.isArray(out.sources) ? out.sources : []), ...(planned[i]?.json.assigned_sources ?? [])];
  for (const src of used) {
    const url = String(src?.url ?? '').trim();
    if (/^https?:\/\//.test(url) && !sources.has(url)) sources.set(url, clean(src.title, 150) || url);
  }
});
if (!sections.length) throw new Error(`No section could be written. ${errors.join(' ')}`);

return [{
  json: {
    revision: 0,
    newsletter: {
      subject: clean(plan.subject, 150),
      subject_alternatives: (Array.isArray(plan.subject_alternatives) ? plan.subject_alternatives : []).map((x) => clean(x, 150)).filter(Boolean).slice(0, 2),
      preview_text: clean(plan.preview_text, 150),
      headline: clean(plan.headline, 120),
      intro: clean(plan.intro, 800),
      sections,
      cta_link: plan.cta_link,
      cta_text: clean(plan.cta_text, 40),
      closing: clean(plan.closing, 400),
    },
    sources: [...sources.entries()].map(([url, title]) => ({ title, url })).slice(0, 12),
    change_summary: '',
    skipped_sections: errors,
  },
}];

// Cleans the newsletter copy and builds the Mailchimp email HTML.
// Runs for the first draft and again after every revision.
const s = $('Settings').first().json;
const t = $('Read Topic').first().json;
const d = $json;
const n = d.newsletter ?? {};
const revision = Number(d.revision) || 0;

// Plain text only: no HTML, and no *| |* that Mailchimp would read as a merge tag
const clean = (v, max) => String(v ?? '').replace(/<[^>]*>/g, '').replace(/\*\||\|\*/g, '').replace(/\s+/g, ' ').trim().slice(0, max);
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const subject = clean(n.subject, 150);
if (!subject) throw new Error('The newsletter has no subject line. Run the workflow again.');
const sections = (Array.isArray(n.sections) ? n.sections : [])
  .map((x) => ({
    title: clean(x?.title, 80),
    paragraphs: (Array.isArray(x?.paragraphs) ? x.paragraphs : []).map((p) => clean(p, 1200)).filter(Boolean).slice(0, 3),
  }))
  .filter((x) => x.paragraphs.length)
  .slice(0, 6);
if (!sections.length) throw new Error('The newsletter has no sections. Run the workflow again.');

const newsletter = {
  subject,
  subject_alternatives: (Array.isArray(n.subject_alternatives) ? n.subject_alternatives : []).map((x) => clean(x, 150)).filter(Boolean).slice(0, 2),
  preview_text: clean(n.preview_text, 150),
  headline: clean(n.headline, 120) || subject,
  intro: clean(n.intro, 800),
  sections,
  cta_link: ['reserve', 'order', 'website'].includes(n.cta_link) ? n.cta_link : 'website',
  cta_text: clean(n.cta_text, 40),
  closing: clean(n.closing, 400),
};

const links = { reserve: s.reservation_url, order: s.order_online_url, website: s.website_url };
const ctaUrl = links[newsletter.cta_link] || s.reservation_url || s.order_online_url || s.website_url;
const ctaText = newsletter.cta_text || (newsletter.cta_link === 'order' ? 'Order now' : newsletter.cta_link === 'reserve' ? 'Book a table' : 'Visit us');
const offer = clean(t.offer, 255);
const color = /^#[0-9a-f]{3,8}$/i.test(String(s.brand_color)) ? s.brand_color : '#7c2d12';

// ---------- Email HTML (table layout with inline styles, so it renders in every email client)
const serif = 'font-family:Georgia,\'Times New Roman\',serif;';
const sans = 'font-family:Arial,Helvetica,sans-serif;';
const p = (text) => `<p style="${sans}font-size:16px;line-height:1.65;color:#44403c;margin:0 0 14px;">${esc(text)}</p>`;
const header = s.logo_url
  ? `<img src="${esc(s.logo_url)}" alt="${esc(s.restaurant_name)}" width="160" style="display:block;margin:0 auto;max-width:160px;height:auto;border:0;">`
  : `<div style="${serif}font-size:24px;text-align:center;color:${color};">${esc(s.restaurant_name)}</div>`;
const button = `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:8px auto 24px;"><tr><td style="background:${color};border-radius:4px;">`
  + `<a href="${esc(ctaUrl)}" style="display:inline-block;padding:14px 30px;${sans}font-size:16px;font-weight:bold;color:#ffffff;text-decoration:none;">${esc(ctaText)}</a></td></tr></table>`;
const sectionHtml = sections.map((x, i) => `<tr><td style="padding:${i ? '8px' : '4px'} 32px 4px;">`
  + `<div style="border-top:1px solid #e7e5e4;padding-top:22px;">`
  + (x.title ? `<h2 style="${serif}font-size:22px;line-height:1.3;font-weight:normal;color:#1c1917;margin:0 0 10px;">${esc(x.title)}</h2>` : '')
  + x.paragraphs.map(p).join('')
  + '</div></td></tr>').join('\n');

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#f5f5f4;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f5f5f4;"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:6px;">
<tr><td style="padding:28px 32px 8px;">${header}</td></tr>
<tr><td style="padding:16px 32px 4px;">
<h1 style="${serif}font-size:30px;line-height:1.2;font-weight:normal;color:#1c1917;margin:0 0 18px;text-align:center;">${esc(newsletter.headline)}</h1>
<p style="${sans}font-size:16px;line-height:1.65;color:#44403c;margin:0 0 14px;">*|IF:FNAME|*Hi *|FNAME|*,*|ELSE:|*Hi there,*|END:IF|*</p>
${newsletter.intro ? p(newsletter.intro) : ''}
${offer ? `<div style="${sans}font-size:16px;font-weight:bold;text-align:center;color:${color};border:2px solid ${color};border-radius:4px;padding:14px;margin:18px 0 6px;">${esc(offer)}</div>` : ''}
</td></tr>
${sectionHtml}
<tr><td style="padding:12px 32px 0;">
${newsletter.closing ? p(newsletter.closing) : ''}
${button}
<p style="${sans}font-size:16px;line-height:1.65;color:#44403c;margin:0 0 24px;">The ${esc(s.restaurant_name)} team</p>
</td></tr>
<tr><td style="padding:20px 32px 28px;border-top:1px solid #e7e5e4;${sans}font-size:12px;line-height:1.6;color:#78716c;text-align:center;">
*|LIST:COMPANY|*<br>*|HTML:LIST_ADDRESS_HTML|*<br>
<a href="*|UNSUB|*" style="color:#78716c;">Unsubscribe</a>
</td></tr>
</table>
</td></tr></table>
</body></html>`;

return [{
  json: {
    revision,
    newsletter,
    sources: Array.isArray(d.sources) ? d.sources : [],
    change_summary: clean(d.change_summary, 400),
    skipped_sections: Array.isArray(d.skipped_sections) ? d.skipped_sections : [],
    subject,
    preview_text: newsletter.preview_text,
    campaign_title: `Newsletter: ${clean(t.topic, 60)} (${t.date}${revision ? `, v${revision + 1}` : ''})`,
    cta_url: ctaUrl,
    html,
  },
}];

// Writes the Telegram approval message: the draft at a glance, the sources to check, and who will get it.
// Telegram reads this message as Markdown, so AI text is escaped (and stripped inside bold labels).
const s = $('Settings').first().json;
const t = $('Read Topic').first().json;
const e = $('Build Email').first().json;
const campaign = $('Create Draft Campaign').first().json;
const recipients = $('Get Campaign Recipients').first().json;
const test = $('Send Test Email').first().json;
const n = e.newsletter;

if (!campaign?.id) {
  throw new Error(`Mailchimp did not create the draft campaign: ${String(campaign?.detail ?? campaign?.error?.message ?? JSON.stringify(campaign)).slice(0, 300)}`);
}

const md = (v) => String(v ?? '').replace(/([_*`[])/g, '\\$1');
const bold = (v) => `*${String(v ?? '').replace(/[_*`[\]]/g, '')}*`;
const cut = (v, max) => {
  const text = String(v ?? '').trim();
  return text.length > max ? `${text.slice(0, max - 1).trimEnd()}…` : text;
};

const count = recipients?.recipients?.recipient_count;
const audience = `${recipients?.recipients?.list_name || 'your Mailchimp audience'}${s.mailchimp_segment_id ? ' (saved segment)' : ''}`;
const testFailed = test?.error || Number(test?.status) >= 400;
const footer = [
  testFailed
    ? `The test email could not be sent: ${md(cut(test.detail ?? test.error?.message ?? test.error, 150))}`
    : `A test email was sent to ${md(s.approver_email)}. Check it before you approve.`,
  `${bold('Audience:')} ${md(audience)}${Number.isFinite(count) ? `, ${count} subscribers` : ''}`,
];

const build = (previewLength, sourceCount) => [
  bold(`Newsletter draft${e.revision ? ` (version ${e.revision + 1})` : ''}: ${cut(t.topic, 80)}`),
  `${bold('Subject:')} ${md(n.subject)}`,
  n.subject_alternatives.length ? `${bold('Other subject ideas:')} ${md(n.subject_alternatives.join(' / '))}` : null,
  `${bold('Preview text:')} ${md(n.preview_text || '(none)')}`,
  e.change_summary ? `${bold('What changed:')} ${md(cut(e.change_summary, 300))}` : null,
  '',
  bold(cut(n.headline, 100)),
  previewLength ? md(cut(n.intro, previewLength + 100)) : null,
  '',
  ...n.sections.map((x, i) => (previewLength
    ? `${bold(`${i + 1}. ${cut(x.title, 80)}`)}\n${md(cut(x.paragraphs[0], previewLength))}`
    : bold(`${i + 1}. ${cut(x.title, 80)}`))),
  '',
  `${bold('Button:')} ${md(n.cta_text)} (${md(e.cta_url)})`,
  t.offer ? `${bold('Offer:')} ${md(t.offer)}` : null,
  e.skipped_sections.length ? `${bold('Left out:')} ${e.skipped_sections.length} section(s) could not be written` : null,
  sourceCount && e.sources.length
    ? `${bold('Sources to check:')}\n${e.sources.slice(0, sourceCount).map((x) => `- ${md(cut(x.title, 70))}: ${md(x.url)}`).join('\n')}`
    : null,
  '',
  ...footer,
].filter((line) => line !== null).join('\n');

// Telegram allows 4,096 characters, so shorten the previews and the source list until it fits
let message = build(260, 5);
for (const [previewLength, sourceCount] of [[160, 5], [100, 3], [0, 3], [0, 0]]) {
  if (message.length <= 3800) break;
  message = build(previewLength, sourceCount);
}

return [{ json: { campaign_id: campaign.id, recipient_count: Number.isFinite(count) ? count : null, telegram_message: message } }];

// Reads the answer from Telegram: send now, schedule, revise with notes, or keep as a draft.
// Telegram returns form answers by field label, so keep these labels in step with the "Ask for Approval" form.
// Mailchimp only schedules on the quarter hour, so times are moved to the next :00, :15, :30, or :45.
const LABELS = { decision: 'What should we do?', sendTime: 'Send time', notes: 'Notes for the editor' };
const s = $('Settings').first().json;
const t = $('Read Topic').first().json;
const e = $('Build Email').first().json;
const brief = $('Build Planning Brief').first().json;
const approval = $('Build Approval Message').first().json;
const answers = $json.data ?? null;
const read = (key) => String(answers?.[LABELS[key]] ?? answers?.[key] ?? '').trim();
const maxRevisions = Number(s.max_revisions) || 3;

let decision = 'draft';
let note = 'No answer in Telegram before the time limit, so the newsletter was kept as a draft.';
let sendTime = '';
let editorPrompt = '';
const choice = read('decision');

if (choice.startsWith('Approve')) {
  decision = 'send_now';
  note = '';
} else if (choice.startsWith('Schedule')) {
  const typed = read('sendTime');
  let when = DateTime.fromFormat(typed, 'yyyy-MM-dd HH:mm', { zone: s.timezone });
  if (!when.isValid) {
    note = `"${typed}" isn't a send time in the format 2026-11-12 11:00, so the newsletter was kept as a draft.`;
  } else {
    const extra = when.minute % 15;
    if (extra) when = when.plus({ minutes: 15 - extra });
    if (when <= $now.plus({ minutes: 15 })) {
      note = `${typed} is less than 15 minutes away or in the past, so the newsletter was kept as a draft.`;
    } else {
      decision = 'schedule';
      sendTime = when.toUTC().toISO({ suppressMilliseconds: true });
      note = `${when.toFormat('cccc, LLL d, yyyy, h:mm a')} (${s.timezone})`;
    }
  }
} else if (choice.startsWith('Revise')) {
  if (e.revision + 1 >= maxRevisions) {
    note = `This was version ${e.revision + 1} of ${maxRevisions}, so it was kept as a draft instead of being revised again.`;
  } else {
    decision = 'revise';
    note = read('notes').slice(0, 1500) || 'Make it more engaging and tighten the writing.';
    const findings = (brief.findings ?? []).map((f, i) => `${i + 1}. ${f.fact} (${f.source_url})`).join('\n');
    editorPrompt = [
      'FEEDBACK FROM THE OWNER',
      note,
      '',
      'CURRENT NEWSLETTER (JSON)',
      JSON.stringify(e.newsletter, null, 2),
      '',
      `Newsletter topic: ${t.topic}`,
      `The owner wants to feature: ${t.feature || 'nothing specific'}`,
      `Offer shown in its own box: ${t.offer || 'none. Do not mention any discount or deal.'}`,
      '',
      'RESEARCH FINDINGS YOU MAY USE',
      findings || 'none',
    ].join('\n');
  }
} else if (answers) {
  note = 'Kept as a draft in Mailchimp, as requested.';
}

return [{
  json: {
    decision,
    note,
    send_time: sendTime,
    editor_prompt: editorPrompt,
    campaign_id: approval.campaign_id,
  },
}];

