// Takes the AI Editor's revised newsletter and sends it back through Build Email as the next version.
const previous = $('Build Email').first().json;
const { change_summary: changeSummary, ...newsletter } = $json.output ?? {};

return [{
  json: {
    revision: previous.revision + 1,
    newsletter: { ...previous.newsletter, ...newsletter },
    sources: previous.sources,
    change_summary: String(changeSummary ?? '').trim(),
    skipped_sections: [],
  },
}];

// Writes the Telegram confirmation: sent, scheduled, kept as a draft, or an error from Mailchimp.
const decision = $('Read Decision').first().json;
const e = $('Build Email').first().json;
const approval = $('Build Approval Message').first().json;
const res = $json;

const md = (v) => String(v ?? '').replace(/([_*`[])/g, '\\$1');
const name = `"${md(e.subject)}"`;
const audience = approval.recipient_count !== null ? ` to ${approval.recipient_count} subscribers` : '';
const failed = res.error || (Number(res.status) >= 400 && res.detail);
const error = failed ? String(res.detail ?? res.error?.message ?? res.error).slice(0, 300) : '';

let text;
if (decision.decision === 'send_now' && !error) {
  text = `✅ *Sending now:* ${name}${audience}.`;
} else if (decision.decision === 'schedule' && !error) {
  text = `🗓 *Scheduled* for ${md(decision.note)}: ${name}${audience}.`;
} else if (error) {
  text = `⚠️ Mailchimp returned an error, so ${name} is still a draft in Mailchimp: ${md(error)}`;
} else {
  text = `📝 ${name} is a draft in Mailchimp. ${md(decision.note)}`;
}

return [{ json: { text } }];
